fn main() {
    let readings = [6, 11, 3, 14, 9];
    let count_exceeding_five = readings.iter().filter(|&&x| x > 5).count();
    let highest_reading = readings.iter().max().unwrap();

    println!("{}", count_exceeding_five);
    println!("{}", highest_reading);
}

fn main() {
    let numbers = [9, 2, 12, 5, 16];
    let mut count = 0;

    for &number in &numbers {
        if number < 10 {
            println!("{}", number);
            count += 1;
        }
    }

    println!("Count of kept entries: {}", count);
}

